import { Component, h, Prop } from '@stencil/core';

@Component({
  tag: 'std-helpertext',
  styleUrl: 'std-helpertext.css',
  shadow: true
})
export class StdHelpertextComponent {
  @Prop() label: string;
  @Prop() status: string;
  @Prop() disabled: boolean;

  render() {
    const statusHelperClasses = {
      default: 'text-soft',
      error: 'text-error',
      warning: 'text-warning',
      success: 'text-success',
      info: 'text-info'
    }[this.status];

    const helperTextClasses = ['flex gap-1 text-sm', this.disabled ? 'text-dark/[0.23]' : statusHelperClasses].join(' ').trim();

    return (
      <p class={helperTextClasses}>
        {this.status !== 'default' && <std-support-icons classes="min-w-5-sl w-5 h-5" type={this.status}></std-support-icons>}
        <span>{this.label}</span>
      </p>
    );
  }
}
